window.kbPageData["views/entry/k-7ab755a1a31ae304"] = {"key":"entry/k-7ab755a1a31ae304","state":{"route":"entry/k-7ab755a1a31ae304"},"node":{"id":"k-7ab755a1a31ae304","mode":"k","title":"城镇调查失业率","type":"概念与词义","domain":"统计","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["统计"],"来源主题":["经济指标与宏观调控"],"资料类别":["非时政"]},"supplement":[{"doc":"6cbfb01fe723bba64b75","file":"《2026年政府工作报告》粉笔解读.pdf","first":3,"last":3,"relation":"辨析","evidenceId":"61504c8428abb3d75bca","cardId":"cb5ae3322fd2f638","questionId":null,"basis":"机构注释","quote":"2.城镇调查失业率调查失业率指根据抽样调查方法测算得到的失业人口占就业人口与失业人口之和的百分比，计算方法为：调查失业率=失业人口/（失业人口+就业人口）×100%。","text":"以失业人口除以就业与失业人口之和。分母是劳动力人口；学生、退休者等是否计入取决于就业或求职状态。","reference":null}],"directorySummary":"以失业人口除以就业与失业人口之和。分母是劳动力人口；学生、退休者等是否计入取决于就业或求职状态。","sources":[{"id":"cb5ae3322fd2f638","label":"城镇调查失业率","topic":"经济指标与宏观调控","category":"非时政","text":"2.城镇调查失业率\n调查失业率指根据抽样调查方法测算得到的失业人口占就业人口与失业人口之和的百\n分比，计算方法为：调查失业率=失业人口/（失业人口+就业人口）×100%。调查失业率与\n经济增长率、物价指数和国际收支平衡状况并称为四大宏观经济指标，是分析宏观经济走\n势和就业形势变化的重要依据，在各个国家均是最重要的经济指标之一。\n——国家统计局","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-7ab755a1a31ae304":[]}};
